const fs=require('fs'),path=require('path'),crypto=require('crypto'),assert=require('assert/strict'),{DatabaseSync,backup}=require('node:sqlite');
const root=path.resolve('evidence/category-restore-20261023/run-'+Date.now());fs.mkdirSync(root,{recursive:true});
(async()=>{const profile=path.join(process.env.APPDATA,'YimuCraft'),config=JSON.parse(fs.readFileSync(path.join(profile,'library-config.json'),'utf8')),db=new DatabaseSync(path.join(config.library,'library.sqlite'));db.exec('PRAGMA foreign_keys=ON; PRAGMA busy_timeout=5000');const source=new DatabaseSync('evidence/category-cleanup-20261023/run-1792768862482/index-before.sqlite',{readOnly:true});
const rows=source.prepare('WITH RECURSIVE t AS (SELECT * FROM collections WHERE parent=1696 UNION ALL SELECT c.* FROM collections c JOIN t ON c.parent=t.id) SELECT * FROM t').all();assert.equal(rows.length,19);
await backup(db,path.join(root,'before.sqlite'));const digest=()=>crypto.createHash('sha256').update(JSON.stringify(db.prepare('SELECT * FROM assets ORDER BY id').all())).digest('hex');const before=digest();const relations=source.prepare('SELECT * FROM collection_assets WHERE collection IN (SELECT value FROM json_each(?))').all(JSON.stringify(rows.map(r=>r.id)));let mappings=[];
db.exec('BEGIN IMMEDIATE');try{const map=new Map();for(const r of rows){const parent=r.parent===1696?null:map.get(r.parent);assert.ok(parent!==undefined);const result=db.prepare('INSERT INTO collections(name,parent,icon,color) VALUES(?,?,?,?)').run(r.name,parent,r.icon,r.color);const id=Number(result.lastInsertRowid);map.set(r.id,id);mappings.push({old:r.id,id,name:r.name,parent});}for(const r of relations){assert.ok(db.prepare('SELECT id FROM assets WHERE id=?').get(r.asset));db.prepare('INSERT INTO collection_assets(collection,asset) VALUES(?,?)').run(map.get(r.collection),r.asset);}assert.equal(digest(),before);db.exec('COMMIT');}catch(e){db.exec('ROLLBACK');throw e;}
const report={root,mappings,relations:relations.length,beforeAssets:before,afterAssets:digest(),parentAbsent:!db.prepare('SELECT 1 FROM collections WHERE id=1696').get(),passed:true};fs.writeFileSync(path.join(root,'report.json'),JSON.stringify(report,null,2));db.close();source.close();console.log(JSON.stringify(report));})().catch(e=>{console.error(e);process.exitCode=1;});
